### Overview of Existing Architecture

From inspecting [`state-crdt.ts`](file:////workspace/realtime-collab-board/state-crdt.ts#L751-L764), [`canvas-engine.ts`](file:////workspace/realtime-collab-board/canvas-engine.ts#L821-L836), and [`ws-client.ts`](file:////workspace/realtime-collab-board/ws-client.ts#L651-L660):

- **[`CanvasStateManager`](file:////workspace/realtime-collab-board/state-crdt.ts#L751-L764)**: Stores active board elements in `Map<string, WhiteboardElement>` keyed by `id`, resolving conflicts via Last-Write-Wins (LWW) on `version` (`incoming.version > current.version`).
- **[`CanvasRenderer`](file:////workspace/realtime-collab-board/canvas-engine.ts#L821-L836)**: Renders elements from `CanvasStateManager.getAllElements()` onto a canvas 2D context using `ViewportTransform`.
- **[`SyncSocketClient`](file:////workspace/realtime-collab-board/ws-client.ts#L651-L660)**: Broadcasts updated `WhiteboardElement` payloads with `{ type: "ELEMENT_SYNC", payload: el }`.

---

### Complete TypeScript Implementation

Below is the complete, drop-in TypeScript implementation for **Multi-user Conflict-free Undo/Redo with Spatial Bounding-Box Invalidation** across the three modules.

#### 1. `state-crdt.ts` — Per-Peer Conflict-Free Undo/Redo (`CanvasStateManager`)

To make undo/redo conflict-free in a multi-user CRDT environment:
1. **Per-peer stacks (`Map<string, UndoRedoStack>`)**: Each `peerId` only undoes/redoes their own authored mutations (`authorId === peerId`) without rolling back concurrent edits from other peers unless the element has not been superseded or we issue a monotonic version increment.
2. **Monotonic Version Bumping for CRDT Convergence**: When a peer undoes or redoes a batch of elements, the restored states receive `version = Math.max(current?.version ?? 0, snapshot.version) + 1` (and a tombstone indicator `width: 0, height: 0` or removal if the element didn't exist prior to creation) so that `applyRemotePatch` on remote peers accepts the undo/redo state over the wire.

```typescript
export interface PeerState {
  peerId: string;
  clock: number;
  lastSeen: number;
}

export interface WhiteboardElement {
  id: string;
  type: string;
  x: number;
  y: number;
  width: number;
  height: number;
  stroke: string;
  version: number;
  authorId: string;
  deleted?: boolean;
}

export interface UndoRedoStack {
  undo: WhiteboardElement[][];
  redo: WhiteboardElement[][];
}

export class CanvasStateManager {
  private elements: Map<string, WhiteboardElement> = new Map();
  private peerStacks: Map<string, UndoRedoStack> = new Map();

  private getPeerStack(peerId: string): UndoRedoStack {
    let stack = this.peerStacks.get(peerId);
    if (!stack) {
      stack = { undo: [], redo: [] };
      this.peerStacks.set(peerId, stack);
    }
    return stack;
  }

  /**
   * Records a local mutation by `peerId` so it can be undone later without
   * clobbering other peers' histories.
   */
  public applyLocalMutation(peerId: string, incomingBatch: WhiteboardElement[]): WhiteboardElement[] {
    const stack = this.getPeerStack(peerId);
    const inverseSnapshot: WhiteboardElement[] = [];
    const applied: WhiteboardElement[] = [];

    for (const incoming of incomingBatch) {
      const prev = this.elements.get(incoming.id);
      if (prev) {
        inverseSnapshot.push({ ...prev });
      } else {
        // Tombstone representing that the element did not exist before this mutation
        inverseSnapshot.push({
          ...incoming,
          width: 0,
          height: 0,
          deleted: true,
        });
      }

      const nextVersion = Math.max(prev?.version ?? 0, incoming.version) + 1;
      const updated: WhiteboardElement = {
        ...incoming,
        authorId: peerId,
        version: nextVersion,
        deleted: incoming.deleted ?? false,
      };
      this.elements.set(updated.id, updated);
      applied.push(updated);
    }

    if (inverseSnapshot.length > 0) {
      stack.undo.push(inverseSnapshot);
      stack.redo = []; // Clear redo history on new local action
    }

    return applied;
  }

  public applyRemotePatch(incoming: WhiteboardElement): boolean {
    const current = this.elements.get(incoming.id);
    if (!current || incoming.version > current.version) {
      if (incoming.deleted) {
        this.elements.delete(incoming.id);
      } else {
        this.elements.set(incoming.id, { ...incoming });
      }
      return true;
    }
    return false;
  }

  /**
   * Undoes the most recent mutation batch authored by `peerId`.
   * Returns the resulting active WhiteboardElement[] snapshot (or the mutated elements).
   */
  public undo(peerId: string): WhiteboardElement[] {
    const stack = this.peerStacks.get(peerId);
    if (!stack || stack.undo.length === 0) {
      return this.getAllElements();
    }

    const targetSnapshots = stack.undo.pop()!;
    const redoSnapshots: WhiteboardElement[] = [];

    for (const target of targetSnapshots) {
      const current = this.elements.get(target.id);
      const nextVersion = Math.max(current?.version ?? 0, target.version) + 1;

      if (current) {
        redoSnapshots.push({ ...current });
      } else {
        redoSnapshots.push({
          ...target,
          width: 0,
          height: 0,
          version: nextVersion - 1,
          deleted: true,
        });
      }

      if (target.deleted) {
        this.elements.delete(target.id);
      } else {
        const restored: WhiteboardElement = {
          ...target,
          authorId: peerId,
          version: nextVersion,
          deleted: false,
        };
        this.elements.set(restored.id, restored);
      }
    }

    stack.redo.push(redoSnapshots);
    return this.getAllElements();
  }

  /**
   * Redoes the most recently undone mutation batch for `peerId`.
   * Returns the resulting active WhiteboardElement[] snapshot.
   */
  public redo(peerId: string): WhiteboardElement[] {
    const stack = this.peerStacks.get(peerId);
    if (!stack || stack.redo.length === 0) {
      return this.getAllElements();
    }

    const targetSnapshots = stack.redo.pop()!;
    const undoSnapshots: WhiteboardElement[] = [];

    for (const target of targetSnapshots) {
      const current = this.elements.get(target.id);
      const nextVersion = Math.max(current?.version ?? 0, target.version) + 1;

      if (current) {
        undoSnapshots.push({ ...current });
      } else {
        undoSnapshots.push({
          ...target,
          width: 0,
          height: 0,
          version: nextVersion - 1,
          deleted: true,
        });
      }

      if (target.deleted) {
        this.elements.delete(target.id);
      } else {
        const restored: WhiteboardElement = {
          ...target,
          authorId: peerId,
          version: nextVersion,
          deleted: false,
        };
        this.elements.set(restored.id, restored);
      }
    }

    stack.undo.push(undoSnapshots);
    return this.getAllElements();
  }

  public getAllElements(): WhiteboardElement[] {
    return Array.from(this.elements.values()).filter((el) => !el.deleted);
  }
}
```

