#### 2. `canvas-engine.ts` — Spatial Bounding-Box Invalidation (`computeDirtyBounds` & Partial Redraw)

`computeDirtyBounds` diffs the `before` and `after` element snapshots in $O(N)$ time using a `Map<string, WhiteboardElement>`. Any element that was **added**, **removed**, or **modified** (position, dimensions, stroke, type, or version) contributes both its old and new axis-aligned bounding boxes (normalized for negative width/height) to the union dirty rectangle.

```typescript
export interface BoundingBox {
  minX: number;
  minY: number;
  maxX: number;
  maxY: number;
}

function getElementBounds(el: WhiteboardElement): BoundingBox {
  const minX = Math.min(el.x, el.x + el.width);
  const maxX = Math.max(el.x, el.x + el.width);
  const minY = Math.min(el.y, el.y + el.height);
  const maxY = Math.max(el.y, el.y + el.height);
  return { minX, minY, maxX, maxY };
}

function hasElementChanged(a: WhiteboardElement, b: WhiteboardElement): boolean {
  return (
    a.x !== b.x ||
    a.y !== b.y ||
    a.width !== b.width ||
    a.height !== b.height ||
    a.stroke !== b.stroke ||
    a.type !== b.type ||
    a.version !== b.version ||
    Boolean(a.deleted) !== Boolean(b.deleted)
  );
}

/**
 * Computes the minimal axis-aligned bounding box enclosing all elements that were
 * added, deleted, moved, resized, or restyled between `before` and `after`.
 * Returns `{ minX: 0, minY: 0, maxX: 0, maxY: 0 }` when no elements changed.
 */
export function computeDirtyBounds(
  before: WhiteboardElement[],
  after: WhiteboardElement[]
): { minX: number; minY: number; maxX: number; maxY: number } {
  const beforeMap = new Map<string, WhiteboardElement>();
  for (const el of before) {
    if (!el.deleted) {
      beforeMap.set(el.id, el);
    }
  }

  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;

  const expand = (el: WhiteboardElement) => {
    const b = getElementBounds(el);
    if (b.minX < minX) minX = b.minX;
    if (b.minY < minY) minY = b.minY;
    if (b.maxX > maxX) maxX = b.maxX;
    if (b.maxY > maxY) maxY = b.maxY;
  };

  for (const afterEl of after) {
    if (afterEl.deleted) continue;
    const beforeEl = beforeMap.get(afterEl.id);
    if (!beforeEl) {
      // Newly added element
      expand(afterEl);
    } else {
      if (hasElementChanged(beforeEl, afterEl)) {
        // Include both old and new bounds so the old position is cleared and new position is drawn
        expand(beforeEl);
        expand(afterEl);
      }
      beforeMap.delete(afterEl.id);
    }
  }

  // Remaining elements in `beforeMap` were deleted in `after`
  for (const removedEl of beforeMap.values()) {
    expand(removedEl);
  }

  if (minX === Infinity) {
    return { minX: 0, minY: 0, maxX: 0, maxY: 0 };
  }

  return { minX, minY, maxX, maxY };
}
```

Integrating `computeDirtyBounds` into [`CanvasRenderer`](file:////workspace/realtime-collab-board/canvas-engine.ts#L821-L836) for partial-region rendering:

```typescript
export class CanvasRenderer {
  private ctx: any;
  private stateManager: CanvasStateManager;
  private vp: ViewportTransform = { zoom: 1, panX: 0, panY: 0 };

  constructor(ctx: any, sm: CanvasStateManager) {
    this.ctx = ctx;
    this.stateManager = sm;
  }

  public renderDirtyRegion(dirty: BoundingBox): void {
    if (dirty.minX === 0 && dirty.minY === 0 && dirty.maxX === 0 && dirty.maxY === 0) {
      return;
    }
    const pad = 2; // Stroke-width safety padding
    const rx = dirty.minX - pad;
    const ry = dirty.minY - pad;
    const rw = dirty.maxX - dirty.minX + pad * 2;
    const rh = dirty.maxY - dirty.minY + pad * 2;

    this.ctx.save?.();
    this.ctx.beginPath?.();
    this.ctx.rect?.(rx, ry, rw, rh);
    this.ctx.clip?.();
    this.ctx.clearRect?.(rx, ry, rw, rh);

    const elements = this.stateManager.getAllElements();
    for (const el of elements) {
      const b = getElementBounds(el);
      const intersects =
        b.maxX >= rx && b.minX <= rx + rw && b.maxY >= ry && b.minY <= ry + rh;
      if (!intersects) continue;

      this.ctx.strokeStyle = el.stroke;
      if (el.type === "rect") {
        this.ctx.strokeRect(el.x, el.y, el.width, el.height);
      }
    }
    this.ctx.restore?.();
  }
}
```

