#### 3. `ws-client.ts` — Broadcasting Undo/Redo Deltas (`SyncSocketClient`)

When `undo(peerId)` or `redo(peerId)` executes locally, only the elements that changed between `before` and `after` (with bumped CRDT `version` numbers) need to be broadcast over WebSocket:

```typescript
export class SyncSocketClient {
  private url: string;
  private ws: any;

  constructor(url: string) {
    this.url = url;
  }

  public broadcastElement(el: WhiteboardElement): void {
    if (this.ws && this.ws.readyState === 1) {
      this.ws.send(JSON.stringify({ type: "ELEMENT_SYNC", payload: el }));
    }
  }

  public broadcastDiff(before: WhiteboardElement[], after: WhiteboardElement[]): void {
    const beforeMap = new Map(before.map((el) => [el.id, el]));
    const afterMap = new Map(after.map((el) => [el.id, el]));

    for (const [id, afterEl] of afterMap) {
      const beforeEl = beforeMap.get(id);
      if (!beforeEl || afterEl.version > beforeEl.version) {
        this.broadcastElement(afterEl);
      }
    }

    for (const [id, beforeEl] of beforeMap) {
      if (!afterMap.has(id)) {
        this.broadcastElement({
          ...beforeEl,
          width: 0,
          height: 0,
          version: beforeEl.version + 1,
          deleted: true,
        });
      }
    }
  }
}
```
